  const mirrorMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.5, metalness: 0.4 });
  const mirrors = [];
  for (const s of [-1, 1]) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.12, 0.22), mirrorMat);
    m.position.set(s * (CAR.width / 2 + 0.1), 1.0, 0.55);
    mirrors.push(m);
