    completeStars: $('completeStars'), completeStats: $('completeStats'),
    completeTitle: $('completeTitle'), failReason: $('failReason'), failTitle: $('failTitle'),
  };
  const mapCtx = mapCanvas.getContext('2d');

  function fmtTime(s) {
