      const locked = i >= game.unlocked;
      b.className = locked ? 'locked' : '';
      const stars = game.best[String(i)] || 0;
      b.innerHTML = `${i + 1}<span class="st">${locked ? '🔒' : '★'.repeat(stars) + '☆'.repeat(3 - stars)}</span>`;
