      const b = bayCenter(row, Number(idx));
      mapCtx.save();
      mapCtx.translate(X(b.x), Z(b.z));
      mapCtx.rotate(-b.heading + Math.PI);
      mapCtx.fillRect(-3.5, -6, 7, 12);
      mapCtx.restore();
    }
    mapCtx.fillStyle = '#ff6a1f';
    for (const c of level.cones || []) {
