      mapCtx.fillRect((-BAY.width / 2) * sx, (-BAY.length / 2) * sy, BAY.width * sx, BAY.length * sy);
      mapCtx.strokeStyle = '#8affc1';
      mapCtx.lineWidth = 2.5;
      mapCtx.strokeRect((-BAY.width / 2) * sx, (-BAY.length / 2) * sy, BAY.width * sx, BAY.length * sy);
      mapCtx.restore();
