      const kmh = Math.round(Math.abs(car.speed) * 3.6);
      const gear = car.speed > 0.2 ? 'D' : car.speed < -0.2 ? 'R' : 'N';
      els.speed.innerHTML = `${kmh}<small> km/h</small><span class="gear">${gear}</span>`;
      els.dmgFill.style.width = `${Math.round(car.damage)}%`;
